import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as e,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MiniMax Agent 学习地图","description":"MiniMax Agent 是通用 Agent 工作台，不是 MiniMax Code。本目录只写网页工作台；Code / Hailuo / 星野只在家族图占一行。","frontmatter":{"title":"MiniMax Agent 学习地图","description":"MiniMax Agent 是通用 Agent 工作台，不是 MiniMax Code。本目录只写网页工作台；Code / Hailuo / 星野只在家族图占一行。","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"zh/products/minimax-agent/index.md","filePath":"zh/products/minimax-agent/index.md","lastUpdated":1787107158000}'),r={name:"zh/products/minimax-agent/index.md"};function s(l,a,o,d,m,p){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="minimax-agent-学习地图" tabindex="-1">MiniMax Agent 学习地图 <a class="header-anchor" href="#minimax-agent-学习地图" aria-label="Permalink to &quot;MiniMax Agent 学习地图&quot;">​</a></h1><blockquote><p><strong>MiniMax Agent</strong> 是 MiniMax 的通用智能体工作台。官方定义（<a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a>）： 「一个能完成长程（Long Horizon）复杂任务的通用智能体，也就是能多步规划出专家级解决方案、能灵活拆解任务需求、并能执行多个子任务从而交付最终结果。」</p><p>国内入口：<a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>。海外入口：<a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a>。</p><p><strong>本目录不写 MiniMax Code 主教程。</strong> 桌面端编程 Agent 见官方 <a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code 欢迎页</a>，本站另 issue #72。</p></blockquote><h2 id="产品全景" tabindex="-1">产品全景 <a class="header-anchor" href="#产品全景" aria-label="Permalink to &quot;产品全景&quot;">​</a></h2><p>MiniMax 官网、Agent 站和文档站用了好几套名字。它们<strong>不是</strong>同一个产品的四张皮。本目录的<strong>主学习路径</strong>是 <strong>MiniMax Agent</strong>（网页通用工作台）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MiniMax 家族</span></span>
<span class="line"><span>├── MiniMax Agent — 通用 Agent 工作台（本目录）</span></span>
<span class="line"><span>│   ├── 网页：agent.minimaxi.com / agent.minimax.io</span></span>
<span class="line"><span>│   ├── Lightning / Pro 两种模式</span></span>
<span class="line"><span>│   ├── 技能市场 /skills</span></span>
<span class="line"><span>│   └── 站内入口：MaxHermes、MaxClaw</span></span>
<span class="line"><span>├── MiniMax Code — 桌面端 Coding Agent（#72，不在本目录展开）</span></span>
<span class="line"><span>├── MiniMax Design / Hub — 多模态创作画布</span></span>
<span class="line"><span>├── Hailuo / 海螺视频 — 视频生成</span></span>
<span class="line"><span>├── MiniMax Audio — 语音与音乐</span></span>
<span class="line"><span>├── 星野 / Talkie — 沉浸式角色社区</span></span>
<span class="line"><span>└── 开放平台 / Token Plan — API 与计费</span></span></code></pre></div><table tabindex="0"><thead><tr><th>官方一级入口</th><th>是什么</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>MiniMax Agent</strong></td><td>通用长程智能体工作台</td><td><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a></td><td>独立页：本目录</td></tr><tr><td>MiniMax Code</td><td>桌面端 AI Agent，面向本地项目 / 终端 / 浏览器</td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code 欢迎页</a></td><td>地图一行。主教程另 #72</td></tr><tr><td>MiniMax Design / Hub</td><td>多模态创作平台。英文 About 仍写 Hub；<code>hub.minimaxi.com</code> 当前加载 Design</td><td><a href="https://design.minimaxi.com/" target="_blank" rel="noreferrer">design.minimaxi.com</a>、<a href="https://hub.minimaxi.com/" target="_blank" rel="noreferrer">hub.minimaxi.com</a></td><td>地图一行</td></tr><tr><td>Hailuo / 海螺视频</td><td>文/图生视频</td><td><a href="https://hailuoai.com/" target="_blank" rel="noreferrer">hailuoai.com</a></td><td>地图一行</td></tr><tr><td>MiniMax Audio</td><td>语音合成与音乐</td><td><a href="https://www.minimaxi.com/audio" target="_blank" rel="noreferrer">minimaxi.com/audio</a></td><td>地图一行</td></tr><tr><td>星野</td><td>沉浸式 AI 内容社区</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">xingyeai.com</a></td><td>地图一行</td></tr><tr><td>Talkie</td><td>星野海外对应</td><td><a href="https://www.talkie-ai.com/" target="_blank" rel="noreferrer">talkie-ai.com</a></td><td>地图一行</td></tr><tr><td>开放平台 / API</td><td>模型 HTTP API</td><td><a href="https://platform.minimaxi.com/" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td><td>地图一行</td></tr><tr><td>Token Plan</td><td>订阅与额度</td><td>厂商站 Product nav「Token Plan」</td><td>地图一行</td></tr><tr><td>About / News / IR</td><td>公司栏目</td><td><a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">minimaxi.com</a></td><td>非本站</td></tr></tbody></table><p>来源：<a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">www.minimaxi.com</a> 关于我们、<a href="https://www.minimaxi.com/en" target="_blank" rel="noreferrer">www.minimaxi.com/en</a> Product / About、<a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>、<a href="https://agent.minimaxi.com/docs/llms.txt" target="_blank" rel="noreferrer">docs/llms.txt</a>。2026-08-19 打开。</p><p><strong>容易撞名的几条：</strong></p><ul><li><strong>MiniMax Agent ≠ MiniMax Code。</strong> Agent 是通用工作台。Code 是桌面端应用。changelog <a href="https://agent.minimaxi.com/docs/changelog" target="_blank" rel="noreferrer">v3.0.33</a> 原文：「桌面端正式更名为 MiniMax Code」。</li><li><strong>MiniMax Hub ≠ MiniMax Agent。</strong> 英文 About 把 Hub 和 Code / Audio / Talkie 并列。当前 <code>hub.minimaxi.com</code> 打开后写的是 MiniMax Design。</li><li><strong>Mini-Agent ≠ MiniMax Agent。</strong> <code>MiniMax-AI/Mini-Agent</code> 是开放平台上的示例项目，不是这款产品。</li><li><strong>MaxHermes / MaxClaw</strong> 出现在 Agent 首页，不是厂商一级产品。见 <a href="./minimax-agent-glossary.html">术语表</a>。</li></ul><p>模型内部（MSA、注意力、训练）见 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。本目录不写机制。</p><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在网页里把一个长任务做完（研究、PPT、报告、网页、多模态交付）</span></span>
<span class="line"><span>│   └── → MiniMax Agent（本目录）</span></span>
<span class="line"><span>│       ├── 问答 / 轻搜索 / 轻代码 → Lightning</span></span>
<span class="line"><span>│       └── 长程研究 / 全栈 / PPT / 报告 / 网页 → Pro；复杂拆解开 Agent Team</span></span>
<span class="line"><span>├── 对着本机仓库写代码、看 diff、跑终端</span></span>
<span class="line"><span>│   └── → MiniMax Code（官方桌面端文档；本站 #72）</span></span>
<span class="line"><span>├── 只做视频</span></span>
<span class="line"><span>│   └── → Hailuo / 海螺视频</span></span>
<span class="line"><span>├── 只做语音 / 音乐</span></span>
<span class="line"><span>│   └── → MiniMax Audio</span></span>
<span class="line"><span>├── 角色扮演 / 沉浸社区</span></span>
<span class="line"><span>│   └── → 星野（国内）/ Talkie（海外）</span></span>
<span class="line"><span>├── 短剧 / 分镜 / 成片画布</span></span>
<span class="line"><span>│   └── → MiniMax Design（域名仍可能显示 Hub）</span></span>
<span class="line"><span>└── 在自己的程序里调模型</span></span>
<span class="line"><span>    └── → 开放平台 API</span></span></code></pre></div><h2 id="什么时候值得试-minimax-agent" tabindex="-1">什么时候值得试 MiniMax Agent <a class="header-anchor" href="#什么时候值得试-minimax-agent" aria-label="Permalink to &quot;什么时候值得试 MiniMax Agent&quot;">​</a></h2><p><strong>什么情况下值得试？</strong></p><ul><li>你要的是<strong>网页里可交付的长程任务</strong>：深度研究、PPT、报告、网页，而不是终端里改仓库。</li><li>你已经在用 Claude.ai / Cowork 一类工作台，想对照国内入口。</li><li>任务需要多模态输出（图 / 音 / 视频）或 MCP 扩展。官方 <a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a> 把编程、多模态、MCP 列为设计标准。</li></ul><p><strong>什么情况下先别急？</strong></p><ul><li>你要的是本机项目、终端、Git 工作区 —— 那是 <strong>MiniMax Code</strong>，不要在这套网页教程里找 CLI。</li><li>你只要出一条视频 —— 走 Hailuo，不要绕 Agent。</li><li>你要角色陪伴 —— 走 星野 / Talkie。</li><li>你需要把命令、权限模式、flag 写成可复制手册 —— 官方没有给 Agent 网页单独的 Commands 页。本站只写能打开的官方原文。</li></ul><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 打开能用</td><td><a href="./minimax-agent.html">MiniMax Agent 教程</a></td><td>登录网页，发出第一个任务</td></tr><tr><td>2. 选对模式</td><td>教程里的 Lightning / Pro，<a href="./minimax-agent-cookbook.html">Cookbook</a></td><td>短问答不走 Pro，长程不走 Lightning</td></tr><tr><td>3. 用技能和 Team</td><td>Cookbook + 官方 <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">技能市场</a></td><td>知道何时装 Skill、何时开 Team</td></tr><tr><td>4. 回查入口</td><td><a href="./minimax-agent-cheatsheet.html">速查表</a></td><td>域名、模式、数据源</td></tr><tr><td>5. 理清名字</td><td><a href="./minimax-agent-glossary.html">术语表</a></td><td>Agent / Code / Hub / Design / Mini-Agent</td></tr></tbody></table><h2 id="功能速查表" tabindex="-1">功能速查表 <a class="header-anchor" href="#功能速查表" aria-label="Permalink to &quot;功能速查表&quot;">​</a></h2><p>下表只列能在官方页找到原文的能力。</p><table tabindex="0"><thead><tr><th>能力</th><th>一句话</th><th>官方原文</th></tr></thead><tbody><tr><td>长程任务</td><td>多步规划、拆解、交付最终结果</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a></td></tr><tr><td>Lightning</td><td>对话问答 / 轻量级搜索 / 轻量级代码，极速输出</td><td><a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 新闻</a></td></tr><tr><td>Pro</td><td>深度研究 / 全栈开发 / PPT / 报告 / 网页制作</td><td><a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 新闻</a></td></tr><tr><td>Agent Team</td><td>主 Agent 拆任务；Leader / Worker / Verifier</td><td><a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team</a></td></tr><tr><td>技能市场</td><td>浏览、安装、自定义或从 GitHub 导入技能</td><td><a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skills</a></td></tr><tr><td>编程</td><td>复杂跳转、模拟用户操作做测试、重视界面</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a></td></tr><tr><td>多模态</td><td>理解长文本 / 视频 / 音频 / 图片；内置生图、音频、视频</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a></td></tr><tr><td>MCP</td><td>内置 MiniMax MCP；官方还写了 GitHub / GitLab / Slack / Figma 等集成</td><td><a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a></td></tr><tr><td>写作 / 语音 / 图像 / 文档 / 翻译</td><td>功能页列出的消费向能力</td><td><a href="https://agent.minimax.io/features/zh.html" target="_blank" rel="noreferrer">features</a></td></tr></tbody></table><p>驱动模型会随产品改版。2026-08-19 首页可见「尝试全新 M3」。模型原理见 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。</p><h2 id="资源链接" tabindex="-1">资源链接 <a class="header-anchor" href="#资源链接" aria-label="Permalink to &quot;资源链接&quot;">​</a></h2><ul><li>产品：<a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">https://agent.minimaxi.com/</a></li><li>海外：<a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">https://agent.minimax.io/</a></li><li>厂商：<a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">https://www.minimaxi.com/</a></li><li>文档索引：<a href="https://agent.minimaxi.com/docs/llms.txt" target="_blank" rel="noreferrer">https://agent.minimaxi.com/docs/llms.txt</a></li><li>完整信息源见 <a href="./minimax-agent-cheatsheet.html#高质量信息源">速查表</a></li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./minimax-agent.html">MiniMax Agent 教程</a></li><li><a href="./minimax-agent-cookbook.html">实战 Cookbook</a></li><li><a href="./minimax-agent-cheatsheet.html">速查表</a></li><li><a href="./minimax-agent-glossary.html">术语表</a></li><li><a href="./../">AI 编程工具总览</a></li></ul>`,27)])])}const b=t(r,[["render",s]]);export{f as __pageData,b as default};
